// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Mint initial liquidity: send 1 ether of base and 1 ether of quote
        vm.deal(address(c), 0);
        c._BASE_TOKEN_().transfer(address(c), 1 ether);
        c._QUOTE_TOKEN_().transfer(address(c), 1 ether);
        c.buyShares(address(this));

        // Call adjustMtFeeRate
        c.adjustMtFeeRate(1e17);

        // The reference contract updates _BASE_RESERVE_ during sync after buyShares.
        // The buggy contract never updates _BASE_RESERVE_, so it stays 0.
        // _BASE_RESERVE_ should be > 0 after buying shares.
        assertTrue(c._BASE_RESERVE_() > 0, "_BASE_RESERVE_ should be positive after buyShares");
    }
}

